<?php
declare(strict_types=1);require_once dirname(__DIR__,2).'/bootstrap.php';
use Artdon\MaterialCenter\Adapters\LegacyAuthAdapter;use Artdon\MaterialCenter\Security\PermissionService;use Artdon\MaterialCenter\Services\SubstitutionService;
header('Content-Type:application/json;charset=utf-8');header('Cache-Control:no-store');
try{$user=(new LegacyAuthAdapter())->current();$permission=new PermissionService();$permission->require($user,'material_center.material.lifecycle');if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf((string)($_POST['csrf_token']??'')))throw new RuntimeException('安全令牌已过期。',419);$service=new SubstitutionService();$action=(string)($_POST['action']??'save');if($action==='save')$data=['id'=>$service->save($_POST,$user->id)];elseif($action==='approve'){$permission->require($user,'material_center.approve');$service->approve((int)$_POST['id'],$user->id);$data=[];}elseif($action==='impact')$data=$service->impact((int)$_POST['material_id']);elseif($action==='migrate'){$permission->require($user,'material_center.material.merge');$data=$service->migrateReferences((int)$_POST['from_material_id'],(int)$_POST['to_material_id'],$user->id);}elseif($action==='rollback'){$permission->require($user,'material_center.material.merge');$data=$service->rollbackMigration((string)$_POST['migration_uuid'],$user->id);}else throw new RuntimeException('操作无效。');echo json_encode(['ok'=>true,'data'=>$data],JSON_UNESCAPED_UNICODE);}
catch(Throwable$e){http_response_code($e->getCode()>=400&&$e->getCode()<600?$e->getCode():422);echo json_encode(['ok'=>false,'message'=>$e->getMessage()],JSON_UNESCAPED_UNICODE);}
